    at async run (/home/geopjr/.npm/_npx/6d9e562882086ed1/node_modules/sponsorkit/dist/cli.cjs:39:16)
    at async Object.handler (/home/geopjr/.npm/_npx/6d9e562882086ed1/node_modules/sponsorkit/dist/cli.cjs:130:3)
```

